# ============================================================
# ACHD Surgical Risk Calculator
# Model: fullerglm_forshiny (logistic regression, rms/rcs splines)
# Required objects in global env:
#   - glm_with_fuller   : fitted glm object
#   - forauc_app        : data.frame with cols prob_fuller, composite_outcome
# ============================================================

library(shiny)
library(bslib)
library(ggplot2)
library(dplyr)
library(rms)

# Tell Shinylive to include this transitive dependency
if (FALSE) {
  library(munsell)
  library(scales)
}

load('data/work_d_for_shiny.RData')
knotlocs <- c(18.5, 25, 30, 35, 40)

#options(datadist = "dd")

# ── Fuller procedure lookup table ─────────────────────────────
fuller_table <- tibble::tribble(
  ~procedure,                                              ~score,
  "ASD repair",                                             0.1,
  "PAPVC",                                                  0.2,
  "Aortic stenosis repair, subvalvular",                    0.2,
  "Conduit reoperation",                                    0.2,
  "Pulmonary valve replacement",                            0.2,
  "Pacemaker procedure",                                    0.2,
  "Anomalous coronary artery from aorta repair",            0.3,
  "Aortic valve repair",                                    0.3,
  "Vascular ring repair",                                   0.3,
  "Ebstein's repair",                                       0.3,
  "Explantation of pacing system",                          0.3,
  "AICD procedure",                                         0.3,
  "AICD implantation",                                      0.3,
  "Pacemaker implantation, permanent",                      0.3,
  "Mitral valve repair",                                    0.4,
  "Konno procedure",                                        0.4,
  "PA reconstruction",                                      0.4,
  "Pulmonic valvuloplasty",                                 0.4,
  "Sinus of Valsalva aneurysm repair",                      0.4,
  "RVOT procedure",                                         0.4,
  "ALCAPA",                                    0.4,
  "Aortic root replacement, valve sparing",                 0.4,
  "PAPVC scimitar",                                         0.4,
  "Aortic stenosis repair, supravalvular",                  0.4,
  "RV aneurysmal repair",                                   0.4,
  "Double-chamber right ventricle repair (DCRV)",           0.4,
  "Ventricular septal defect repair",                       0.5,
  "Common AV canal repair, incomplete",                     0.5,
  "Aortic arch repair",                                     0.5,
  "Aortic valve replacement",                               0.6,
  "Aortic aneurysm repair",                                 0.6,
  "Tricuspid valve repair",                                 0.6,
  "Systemic venous stenosis repair",                        0.6,
  "TOF repair",                                             0.6,
  "Ross procedure",                                         0.7,
  "Conduit placement, RV-PA",                               0.7,
  "Arrhythmia surgery – ablation, ventricular",             0.7,
  "Coarctation repair",                                     0.8,
  "Arrhythmia surgery – ablation, atrial",                  0.8,
  "Pericardial drainage",                                   0.8,
  "Conduit placement, other",                               0.9,
  "Tricuspid valve replacement",                            0.9,
  "ASD creation/enlargement",                               1.0,
  "Aortic root replacement, non-valve sparing",             1.0,
  "Shunt, systemic to pulmonary",                           1.0,
  "Mitral valve replacement",                               1.5,
  "Cardiac tumor resection",                                1.5,
  "Coronary artery bypass (congenital heart)",              1.6,
  "Fontan procedure",                                       1.8,
  "Lung transplantation",                                   2.2,
  "Heart transplantation",                                  2.2,
  "Fontan revision",                                        3.0
) %>% arrange(score, procedure)

fuller_choices <- setNames(
  as.list(as.character(fuller_table$score)),
  sprintf("[%.1f]  %s", fuller_table$score, fuller_table$procedure)
)

# Observed ranges from training data (for out-of-range warnings)
obs_ranges <- list(
  bmi     = c(16, 54),
  albumin = c(18, 53),
  age     = c(3,  82)
)

# ── UI ────────────────────────────────────────────────────────
ui <- page_fluid(
  theme = bs_theme(
    version    = 5,
    bootswatch = "flatly",
    primary    = "#1b4f72",
    "sidebar-bg" = "#eaf0f6"
  ),

  # ── Full-width title bar ──────────────────────────────────
  div(
    class = "w-100 py-3 px-4 mb-4",
    style = "background-color:#1b4f72; color:white;",
    tags$h1(
      style = "font-size:1.55rem; font-weight:700; margin:0; line-height:1.3;",
      "Hybrid patient- and procedure-based perioperative risk in ACHD surgery"
    )
  ),

  # ── Main content: inputs then outputs, stacking on narrow ──
  div(
    class = "container-fluid px-4",

    # ── INPUT SECTION ─────────────────────────────────────
    div(
      class = "card mb-4",
      style = "background-color:#eaf0f6; border:none;",
      div(
        class = "card-body py-3",

        # Disclaimer
        div(
          class = "alert alert-warning p-2 mb-3",
          style = "font-size:0.82rem; line-height:1.4;",
          tags$strong("⚠ Research use only."),
          " This model was derived from a training cohort and",
          " has not been externally validated.",
          " Predictions do not replace clinical judgement."
        ),

        # ── Row 1: BMI / Age / Albumin ─────────────────
        div(
          class = "row g-3 mb-2",

          div(
            class = "col-12 col-sm-4",
            tags$label("BMI (kg/m²)", class = "form-label fw-semibold mb-1"),
            numericInput("bmi", label = NULL,
                         value = 27, min = 0, max = 100, step = 0.1),
            uiOutput("warn_bmi")
          ),

          div(
            class = "col-12 col-sm-4",
            tags$label("Age (years)", class = "form-label fw-semibold mb-1"),
            numericInput("age", label = NULL,
                         value = 41, min = 0, max = 100, step = 1),
            uiOutput("warn_age")
          ),

          div(
            class = "col-12 col-sm-4",
            tags$label("Albumin (g/L)", class = "form-label fw-semibold mb-1"),
            numericInput("albumin", label = NULL,
                         value = 41, min = 0, max = 100, step = 0.5),
            uiOutput("warn_albumin")
          )
        ),

        # ── Row 2: Cognitive impairment / Ventricular dysfunction / Prior incisions ──
        div(
          class = "row g-3 mb-2",

          # Cognitive impairment
          div(
            class = "col-12 col-sm-4",
            tags$label(
              HTML("Cognitive impairment<br><small class='text-muted fw-normal'>Third party signing informed consent</small>"),
              class = "form-label fw-semibold mb-1"
            ),
            div(
              class = "btn-group w-100",
              role  = "group",
              tags$button(
                id = "btn_cogn_no", type = "button",
                class = "btn btn-outline-primary active",
                onclick = "setBinary('cogn', 0)", "No"
              ),
              tags$button(
                id = "btn_cogn_yes", type = "button",
                class = "btn btn-outline-primary",
                onclick = "setBinary('cogn', 1)", "Yes"
              )
            ),
            tags$input(type = "hidden", id = "cogn_impair_val", value = "0")
          ),

          # Ventricular dysfunction
          div(
            class = "col-12 col-sm-4",
            tags$label(
              HTML("Ventricular dysfunction<br><small class='text-muted fw-normal'>Ejection Fraction &lt; 40%</small>"),
              class = "form-label fw-semibold mb-1"
            ),
            div(
              class = "btn-group w-100",
              role  = "group",
              tags$button(
                id = "btn_ef_no", type = "button",
                class = "btn btn-outline-primary active",
                onclick = "setBinary('ef', 0)", "No"
              ),
              tags$button(
                id = "btn_ef_yes", type = "button",
                class = "btn btn-outline-primary",
                onclick = "setBinary('ef', 1)", "Yes"
              )
            ),
            tags$input(type = "hidden", id = "compr_EF_val", value = "0")
          ),

          # Prior incisions
          div(
            class = "col-12 col-sm-4",
            tags$label(
              "Prior chest wall incisions",
              class = "form-label fw-semibold mb-1"
            ),
            tags$small("Sternotomy / thoracotomy", class = "text-muted d-block mb-1"),
            div(
              class = "btn-group w-100 flex-wrap",
              role  = "group",
              lapply(0:5, function(i) {
                tags$button(
                  id      = paste0("btn_inc_", i),
                  type    = "button",
                  class   = if (i == 0) "btn btn-outline-primary active" else "btn btn-outline-primary",
                  onclick = sprintf("setIncisions(%d)", i),
                  as.character(i)
                )
              })
            ),
            tags$input(type = "hidden", id = "prior_incisions_val", value = "0")
          )
        ),

        # ── Row 3: ACHS Score + Calculate button ──────
        div(
          class = "row g-3 align-items-end",

          # ACHS mode + input
          div(
            class = "col-12 col-sm-8",
            tags$label("ACHS Complexity Score", class = "form-label fw-bold mb-1"),
            div(
              class = "d-flex align-items-center gap-3 mb-2",
              radioButtons("fuller_mode", label = NULL,
                           choices  = c("Enter score directly" = "direct",
                                        "Select procedure"     = "lookup"),
                           selected = "direct",
                           inline   = TRUE)
            ),
            conditionalPanel(
              condition = "input.fuller_mode == 'direct'",
              numericInput("max_score_direct",
                           label = "Score (0.1 – 3.0)",
                           value = 0.5, min = 0.1, max = 3.0, step = 0.1)
            ),
            conditionalPanel(
              condition = "input.fuller_mode == 'lookup'",
              selectInput("max_score_lookup",
                          label     = "Select procedure",
                          choices   = fuller_choices,
                          selected  = "0.5",
                          width     = "100%",
                          size      = 10,
                          selectize = FALSE)
            )
          ),

          # Calculate button
          div(
            class = "col-12 col-sm-4 d-flex align-items-end",
            actionButton("calculate", "Calculate Risk",
                         class = "btn btn-primary w-100 fw-bold fs-5",
                         icon  = icon("calculator"))
          )
        )
      )
    ),

    # ── OUTPUT SECTION ────────────────────────────────────
    div(
      class = "row g-4 mb-4",

      # Predicted Risk card
      div(
        class = "col-12 col-md-6",
        card(
          card_header(tags$strong("Predicted Risk")),
          card_body(
            uiOutput("risk_display"),
            hr(),
            uiOutput("percentile_display")
          )
        )
      ),

      # Distribution plot card
      div(
        class = "col-12 col-md-6",
        card(
          card_header(tags$strong("Position in Reference Cohort")),
          card_body(
            plotOutput("dist_plot", height = "300px"),
            div(
              class = "text-muted mt-2",
              style = "font-size:1rem;",
              "Density of predicted probabilities in the training cohort (n = ",
              textOutput("n_cohort", inline = TRUE), ").",
              " Blue = no outcome; red = outcome.",
              " Dashed red line = this patient's predicted probability."
            )
          )
        )
      ),
      # ── FOOTER INFORMATION ─────────────────────────────
      div(
        class = "card mt-2",
        style = "border:none; background-color:#f8fafc;",
        div(
          class = "card-body text-center",
          style = "font-size:0.85rem; line-height:1.5;",

          tags$b("About this calculator"),
          #tags$br(),
          #"Hybrid patient- and procedure-based perioperative risk prediction in ACHD surgery.",

          tags$br(), #tags$br(),

          tags$b("Reference"),
          tags$br(),
          "Ponzoni, M., Sugimoto, A., et al.: Preoperative Predictors of Outcome for Adults Undergoing Congenital Cardiac Surgery: Multicenter Model Validation.",
          tags$em(" The Journal of Thoracic and Cardiovascular Surgery, 2026."),
          tags$br(),
          tags$a(
            href = "https://doi.org/XXXX",
            target = "_blank",
            "View publication"
          ),

          tags$br(), tags$br(),

          tags$b("Contact"),
          tags$br(),
          tags$a(
            href = "mailto:brigitte.mueller@uhn.ca",
            "brigitte.mueller@uhn.ca"
          )
        )
      )
    )
  ),

  # ── JS for binary toggles and incision selector ───────────
  tags$head(tags$style(HTML("
      select#max_score_lookup {
        font-family: monospace;
        font-size: 0.82rem;
        overflow-x: auto;
      }
      select#max_score_lookup option {
        white-space: nowrap;
      }
    ")), tags$script(HTML("
    function setBinary(field, val) {
      if (field === 'cogn') {
        document.getElementById('cogn_impair_val').value = val;
        document.getElementById('btn_cogn_no').classList.toggle('active', val === 0);
        document.getElementById('btn_cogn_yes').classList.toggle('active', val === 1);
      } else {
        document.getElementById('compr_EF_val').value = val;
        document.getElementById('btn_ef_no').classList.toggle('active', val === 0);
        document.getElementById('btn_ef_yes').classList.toggle('active', val === 1);
      }
      Shiny.setInputValue(field === 'cogn' ? 'cogn_impair_val' : 'compr_EF_val', String(val));
    }

    function setIncisions(n) {
      document.getElementById('prior_incisions_val').value = n;
      for (var i = 0; i <= 5; i++) {
        var btn = document.getElementById('btn_inc_' + i);
        if (btn) btn.classList.toggle('active', i === n);
      }
      Shiny.setInputValue('prior_incisions_val', n);
    }

    document.addEventListener('DOMContentLoaded', function() {
      Shiny.setInputValue('cogn_impair_val', '0');
      Shiny.setInputValue('compr_EF_val',    '0');
      Shiny.setInputValue('prior_incisions_val', 0);
    });
  ")))
)

# ── Server ────────────────────────────────────────────────────
server <- function(input, output, session) {

  # Out-of-range warnings
  make_warn <- function(val, varname) {
    renderUI({
      req(!is.na(val()))
      lo <- obs_ranges[[varname]][1]
      hi <- obs_ranges[[varname]][2]
      if (!is.null(val()) && (val() < lo || val() > hi)) {
        div(class = "alert alert-danger p-1 mt-1",
            style = "font-size:0.75rem;",
            sprintf("⚠ Outside training range (%.0f – %.0f): extrapolation applies.", lo, hi))
      }
    })
  }

  output$warn_bmi     <- make_warn(reactive(input$bmi),     "bmi")
  output$warn_age     <- make_warn(reactive(input$age),     "age")
  output$warn_albumin <- make_warn(reactive(input$albumin), "albumin")

  # ── Prediction ──────────────────────────────────────────────
  result <- eventReactive(input$calculate, {

    fuller_raw <- if (input$fuller_mode == "direct") {
      as.numeric(input$max_score_direct)
    } else {
      as.numeric(input$max_score_lookup)
    }
    max_score_model <- fuller_raw * 10

    new_pt <- data.frame(
      bmi             = as.numeric(input$bmi),
      cogn_impair     = as.integer(input$cogn_impair_val %||% 0),
      prior_incisions = as.integer(input$prior_incisions_val %||% 0),
      albumin         = as.numeric(input$albumin),
      age             = as.numeric(input$age),
      compr_EF        = as.integer(input$compr_EF_val %||% 0),
      max_score       = max_score_model
    )

    lp   <- predict(fullerglm_forshiny, newdata = new_pt, type = "link")
    prob <- plogis(lp)

    ref_probs <- forauc_app$prob_fuller
    pctile    <- round(100 * mean(ref_probs <= prob, na.rm = TRUE), 1)

    list(
      prob         = as.numeric(prob),
      lp           = as.numeric(lp),
      pctile       = pctile,
      fuller_shown = fuller_raw
    )
  })

  # ── Risk display ─────────────────────────────────────────────
  output$risk_display <- renderUI({
    req(result())
    prob   <- result()$prob
    pct    <- round(prob * 100, 1)
    pctile <- result()$pctile
    color  <- if (pctile > 75) "#c0392b" else if (pctile > 50) "#d68910" else "#1e8449"

    tagList(
      div(style = "text-align:center; padding: 12px 0;",
          tags$span(
            style = sprintf("font-size:3.9rem; font-weight:800; color:%s; line-height:1;", color),
            sprintf("%.1f%%", pct)
          ),
          tags$br(),
          tags$span(
            style = "font-size:0.82rem; color:#666;",
            sprintf("ACHS score entered: %.1f", result()$fuller_shown)
          )
      )
    )
  })

  # ── Percentile display ────────────────────────────────────────
  output$percentile_display <- renderUI({
    req(result())
    pctile <- result()$pctile
    color  <- if (pctile > 75) "#c0392b" else if (pctile > 50) "#d68910" else "#1e8449"

    div(
      style = "text-align:center; padding:8px 0;",

      tags$span(style = "font-size:0.88rem; color:#555;",
                "Percentile vs. training cohort"),
      tags$br(),

      tags$span(
        style = sprintf("font-size:2.8rem; font-weight:700; color:%s;", color),
        pctile, tags$sup("th", style = "font-size:1.4rem;")
      ),

      tags$br(),

      tags$span(
        style = "font-size:0.78rem; color:#888;",
        sprintf("Higher than %.1f%% of training cohort predictions", pctile)
      )

    )
  })

  # ── Distribution plot ─────────────────────────────────────────
  output$dist_plot <- renderPlot({
    req(result())
    prob <- result()$prob

    ref_data <- forauc_app %>%
      mutate(
        outcome_label = factor(
          composite_outcome,
          levels = c(0, 1),
          labels = c("No composite outcome", "Composite outcome")
        )
      )

    ggplot(ref_data, aes(x = prob_fuller, fill = outcome_label)) +
      geom_histogram(
        aes(y = after_stat(density)),
        bins      = 45,
        alpha     = 0.70,
        position  = "stack",
        colour    = "white",
        linewidth = 0.15
      ) +
      geom_vline(
        xintercept = prob,
        colour     = "#c0392b",
        linewidth  = 1.3,
        linetype   = "dashed"
      ) +
      annotate(
        "label",
        x      = pmin(prob + 0.03, 0.85),
        y      = Inf,
        vjust  = 1.6,
        label  = sprintf("This patient\n%.1f%%", prob * 100),
        colour = "#c0392b",
        fill   = "white",
        size   = 5,
        label.size = 0.3,
        fontface   = "bold"
      ) +
      scale_fill_manual(
        values = c(
          "No composite outcome" = "#aed6f1",
          "Composite outcome"    = "#f1948a"
        )
      ) +
      scale_x_continuous(
        labels = scales::percent_format(accuracy = 1),
        limits = c(0, 1),
        breaks = seq(0, 1, 0.1)
      ) +
      labs(
        x    = "Predicted probability",
        y    = "Density",
        fill = NULL
      ) +
      theme_minimal(base_size = 12) +
      theme(
        legend.position  = "top",
        legend.text      = element_text(size = 15),
        legend.title     = element_text(size = 16),
        axis.title       = element_text(size = 18, face = "bold"),
        axis.text        = element_text(size = 15),
        axis.text.x      = element_text(angle = 30, hjust = 1),
        plot.title       = element_text(size = 20, face = "bold"),
        plot.subtitle    = element_text(size = 16),
        panel.grid.minor = element_blank()
      )
  })

  output$n_cohort <- renderText(nrow(forauc_app))
}

# Null coalescing helper
`%||%` <- function(a, b) if (!is.null(a) && !is.na(a) && nchar(as.character(a)) > 0) a else b

shinyApp(ui, server)
